INSERT INTO system_species (id,name,classification,homeworld_system,physiology,psychology,special_ability) VALUES ('1','Terran Human','Human',NULL,'Bipedal mammalian, adaptable to wide range of environments. Standard oxygen breathers with carbon-based biology.','Curious, ambitious, fractious. Form complex social hierarchies but prone to internal conflict. Innovative under pressure.','Adaptable - Can thrive in any habitable environment');
INSERT INTO system_species (id,name,classification,homeworld_system,physiology,psychology,special_ability) VALUES ('2','Ninevite','NearHuman','NINEVEH','Tall (2.2m avg), slender builds. Pale skin with subtle bioluminescence. Large eyes adapted to bright light. Extended lifespan (200+ years).','Hierarchical, patient, long-term planners. Value knowledge and tradition. Can appear aloof to outsiders.','Light-Adapted - Reduced combat penalties in high-radiation zones');
INSERT INTO system_species (id,name,classification,homeworld_system,physiology,psychology,special_ability) VALUES ('3','Lithoid','Xenoform','ELAM','Silicon-based life, crystalline exoskeleton. Slow-moving but incredibly durable. Communicate through subsonic vibrations. No need for atmosphere.','Methodical, territorial, literal-minded. Think in geological timescales. Suspicious of rapid change.','Radiation Immune - No damage from radiation zones');
INSERT INTO system_species (id,name,classification,homeworld_system,physiology,psychology,special_ability) VALUES ('4','Kethrani','Xenoform','AKKAD','Aquatic origin, amphibious. Scaled skin, gill slits, webbed digits. Can survive in water or standard atmosphere. Chromatic skin displays emotion.','Gregarious, mercantile, consensus-driven. Natural traders and negotiators. Memory for debts and favors.','Trade Affinity - +1 resource when using trade hubs');
INSERT INTO system_species (id,name,classification,homeworld_system,physiology,psychology,special_ability) VALUES ('5','Vesh','Xenoform','GIRSU','Insectoid, hive-based. Individual drones are semi-autonomous but linked to hive consciousness. Varied castes for different functions.','Collective, efficient, alien priorities. Communicate through pheromones and gestures. Difficult for individuals to comprehend.','Hive Labor - Facilities produce +50% at Vesh populations');
INSERT INTO system_species (id,name,classification,homeworld_system,physiology,psychology,special_ability) VALUES ('6','The Remnant','Machine','SUMER','Artificial constructs of unknown origin. Humanoid frames with crystalline cores. Self-repairing. No biological needs.','Cold logic, inscrutable goals. Claim to serve ancient directives. Cooperative but unpredictable.','Machine Precision - Repair costs reduced by 1 resource');
INSERT INTO system_species (id,name,classification,homeworld_system,physiology,psychology,special_ability) VALUES ('7','Wanderers','Human',NULL,'Baseline human stock but culturally distinct. Born and raised on generation ships. Pale, thin from low-gravity environments.','Nomadic, pragmatic, clannish. Distrust of planetary populations. Expert shiphandlers and traders.','Fleet-Born - Ships built at Wanderer facilities get +1 PD');
INSERT INTO system_species (id,name,classification,homeworld_system,physiology,psychology,special_ability) VALUES ('8','The Absent','Elder',NULL,'Unknown. No living specimens. Evidence suggests enormous scale, non-carbon biology, possible dimensional or temporal capabilities.','Unknown. Artifacts suggest vast intellect, incomprehensible motivations. May still exist elsewhere/elsewhen.','Unknown - Artifacts may have unpredictable effects');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('1','SONAL','Sonal Prime','G','Main','Yellow','4.2','Sol-like star. Stable and life-giving. The heart of the Western Alliance.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('2','UR','Ur Alpha','K','Main','Orange','6.8','Primary of ancient binary pair. Warm light bathes the inner worlds.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('3','UR','Ur Beta','M','Dwarf','Red','6.8','Companion star. Small and distant. Stable L4 colonies orbit between.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('4','LARSU','Larsu Sol','F','Main','Yellow-White','2.1','Young and energetic. Intense UV output scorches inner planets.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('5','NINEVEH','Nineveh Ascendant','A','Main','White','0.8','Brilliant young star. Harsh radiation but immense energy output.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('6','BABYLON','Babylon Prima','G','Main','Yellow','5.1','Mature and stable. Extensive habitable zone supports dense populations.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('7','UGARIT','Ugarit Dusk','K','Main','Orange','8.2','Ancient star entering late life. Amber light speaks of long history.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('8','SIPPUR','Sippur Flame','K','Main','Orange','5.4','Steady orange glow. First waypoint from Sonal.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('9','ERECH','Erech Wanderer','G','Main','Yellow','3.8','Standard yellow star. Junction between UR and ADAB.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('10','CALAH','Calah Distant','K','Main','Orange','7.1','Cool orange star at edge of contested space.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('11','BYBLOS','Byblos Shimmer','F','Main','Yellow-White','1.8','Young bright star. Belts form prominent rings visible to naked eye.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('12','ADAB','Adab Nexus','G','Main','Yellow','4.5','Central star. Three warplines make this a crucial waypoint.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('13','SUSA','Susa Ancient','K','Main','Orange','8.9','One of the oldest stars in charted space. Slow and steady.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('14','UBAID','Ubaid Pale','K','Subgiant','Orange','9.2','Slightly expanded. Beginning transition to later stellar phases.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('15','NIPPUR','Nippur Axis','G','Main','Yellow-Orange','3.4','Strategic hub. Four warplines connect here.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('16','KHAFA','Khafa Ember','M','Dwarf','Red','10.2','Dim red dwarf. Cold outer reaches despite proximity to ADAB.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('17','MARI','Mari Torch','F','Main','Yellow-White','2.3','Bright and hot. Inner planets are scorched wastelands.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('18','LAGASH','Lagash Beacon','G','Main','Yellow','4.1','Clear and steady. Major crossroads of central space.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('19','ASSUR','Assur Vigil','K','Main','Orange','6.2','Steady orange star. Close neighbor to Lagash.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('20','SUMARRA','Sumarra Fade','M','Dwarf','Red','11.1','Ancient red dwarf. Minimal energy. Harsh living conditions.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('21','ELAM','Elam Vermillion','M','Dwarf','Red','9.1','Ancient stable red dwarf. Source of exotic Keplerite deposits.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('22','JARMO','Jarmo Spark','G','Main','Yellow','3.1','Young yellow star. Gateway from central space to eastern territories.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('23','UMMA','Umma Hearth','K','Main','Orange','5.6','Warm orange. Four warplines make this heavily contested.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('24','GIRSU','Girsu Drone','M','Dwarf','Red','8.4','Dim red light. Homeworld of the Vesh hive collective.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('25','ISIN','Isin Pale','K','Dwarf','Orange','7.8','Small orange dwarf. Direct route to Nineveh.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('26','SUMER','Sumer Eternal','G','Subgiant','Yellow','6.1','Slightly expanded. Home to the mysterious Remnant machines.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('27','AKKAD','Akkad Jewel','F','Main','Yellow-White','2.8','Bright star with extensive liquid water worlds. Kethrani homeworld.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('28','KISH','Kish Beacon','F','Main','Yellow-White','1.9','Brilliant young star. Three-way junction near eastern territories.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('29','ERIDU','Eridu Setting','K','Main','Orange','7.4','Warm orange light. Gateway to Ugarit.');
